def find_max_value(expression):
    # Replace AND, OR, and XOR with their binary equivalents
    replaced_expression = expression.replace('&', '^').replace('|', '^').replace('^', '&')
    # Replace all non-decimal operators with decimal operators
    replaced_expression = replaced_expression.replace('-', '^').replace('/', '^').replace('*', '*')
    # Replace decimal operators with their binary equivalents
    operators = {'-', '^', '/', '^', '*': '^'}
    for operator, equivalent in operators.items():
        replaced_expression = replaced_expression.replace(operator, equivalent)
    # Replace all second decimal operators with their binary equivalents
    reordered_expression = replaced_expression.replace('&', '^').replace('|', '^').replace('^', '&')
    return evaluated(reordered_expression)

def evaluated(expression):
    # Evaluate the expression based on prefix computation
    operators = {'&': '0', '|': '1', '^': expression}
    MAX_VAL = int(expression[-1], base=2)
    for op in expression[:1:-1]:
        check = operators[op]
        MAX_VAL = check if check == 0 else MAX_VAL ^ check
    return MAX_VAL

def main():
