from typing import List
from collections import defaultdict

def count_ways(n: int, edges: List[List[int]]) -> int:
    adj_matrix = [[0] * n for _ in range(n)]
    visited = [False] * n
    cycles = defaultdict(int)

    def dfs(node: int, previous_node: int):
        visited[node] = True
        cycles[node] = 1

        for neighbor in range(n):
            if adj_matrix[node][neighbor] and neighbor != previous_node:
                if not visited[neighbor]:
                    cycles[node] += dfs(neighbor, node)
                else:
                    cycles[node] += cycles[neighbor]

        return cycles[node]

    for u, v in edges:
        if adj_matrix[u-1][v-1] == 0 and adj_matrix[v-1][u-1] == 0:
            adj_matrix[u-1][v-1] = 1
            adj_matrix[v-1][u-1] = 1

    num_ways = 0
    for i in range(n):
        if not visited[i]:
            ways = dfs(i, -1)
            num_ways += ways * (ways - 1)

    return num_ways

