class EvaluateExpression:
    def __init__(self, string):
        self.string = string
        self.operators = {}
        self.stack = []
        self.res = []

    def evaluate(self):
        stack = []
        operators_stack = []

        for char in self.string:
            if char.isdigit():
                stack.append(char)
            else:
                operators_stack.append(self.operators[char])

        while operators_stack:
            max_val = stack.pop()
            operators1, op_symbol, operators2 = None, operators_stack.pop(), stack.pop()
            if op_symbol == '|':
                operators1 = operators1 or operators
                operators2 = operators2 or operators
            if op_symbol == '&':
                operators1 = operators1 and operators
                operators2 = operators2 and operators
            if op_symbol == '^':
                operators1 = operators1 ^ operators
                operators2 = operators2 ^ operators
            self.res.append(int(max(operators1, operators2)))

        self.res = list(OrderedDict.fromkeys(self.res))
        return max(self.res)


