import sys

class SegmentTree:
    def __init__(self, arr):
        self.arr = arr
        self.tree = [0] * (4 * len(arr))
        self.build(0, len(arr) - 1, 1)

    def build(self, lo, hi, node):
        if lo == hi:
            self.tree[node] = self.arr[lo]
        else:
            mid = (lo + hi) // 2
            self.build(lo, mid, 2 * node)
            self.build(mid + 1, hi, 2 * node + 1)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, dest, change, low, high, node=1):
        if dest < low or high < dest:
            return self.tree[node]
        elif low >= dest and high <= dest:
            self.tree[node] += change
            return self.tree[node]
        else:
            mid = (low + high) // 2
            left = self.update(dest, change, low, mid, 2 * node)
            right = self.update(dest, change, mid + 1, high, 2 * node + 1)
            self.tree[node] = left + right
            return self.tree[node]

    def query(self, lo, hi):
        return self.query_result(0, len(self.tree) - 1, lo, hi)

    def query_result(self, lo, hi, low, high):
        if lo > hi or lo >= low and high <= hi:
            return self.tree[1]
        else:
            mid = (lo + hi) // 2
            left = self.query_result(lo, mid, low, high)
            right = self.query_result(mid + 1, hi, low, high)
            return left + right


