def fisher_yates_shuffle(lst):
    n = len(lst)
    for i in range(n-1, 0, -1):
        j = random.randint(0, i)
        lst[i], lst[j] = lst[j], lst[i]

def is_bridge(node1, node2, adj):
    adj[node1].remove(node2)
    adj[node2].remove(node1)

def build_adj_list(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return adj

def solve(n, m, edges):
    adj = build_adj_list(n, edges)
    fisher_yates_shuffle(edges)

    dp = [0 for _ in range(n)]
    for i in range(n):
        dp[i] = 1
        if adj[i]:
            for j in adj[i]:
                is_bridge(i, j, adj)
                if adj[i]:
                    dp[i] += solve(len(adj[j]), n + len(adj[j]) - 1, min(edges + [(j, n) for n in adj[j]], key=lambda x: x[1]))
                is_bridge(i, j, adj)
    return dp.count(1)

