def is_lucky_number(num):
    return all(digit in '47' for digit in str(num))

def generate_lucky_numbers(l, r):
    if l >= r:
        return []

    def backtrack(start, prev_val):
        if start == len(str(r)):
            return [prev_val]
        if start == len(str(l)) - 1:
            return backtrack(start + 1, prev_val + str(int(str(l)[start]), 2)) + [prev_val]
        combinations = []
        next_num = str(int(str(l)[start:])+2 if (int(str(l)[start:])+2) % 2 === 0 else int(str(l)[start:]) + 1)  # +1 for odd numbers
        if is_lucky_number(next_num):
            combinations.extend([prev_val + int(next_num)[1:], prev_val + str(int(next_num, 2))])
        combinations.extend(backtrack(start + 1, prev_val + int(next_num)[1:] if len(int(next_num)) == len(str(r)[0:start+1]) else int(next_num, 2)))
        return combinations

    return backtrack(0, '')

def solve(l, r):
    unique_lucky_numbers = set()
    for num_str in generate_lucky_numbers(l, r):
        unique_lucky_numbers.add(int(num_str))

    mod = 10**9 + 7
    total = 0
    for i in range(1, len(unique_lucky_numbers)):
        total = (total + (unique_lucky_numbers[i-1] * unique_lucky_numbers[i]) % mod) % mod

    return int(total)
