def build(char_list, length, values):
    max_length = 0
    tree = defaultdict(list)
    for i, val in enumerate(values):
        length2 = len(tree)
        for c in char_list:
            new_index = i + (val * c % (length2*length))
            tree[new_index].append(i)
        assert(len(tree[max_length]) >= 2)
        max_length = new_index

    for i in range(max_length+length-1, max_length, -length):
        if (i not in tree) or (len(tree[i]) == 1):
            tree.pop(i)
    return tree

def query(tree, length, query_range, axis):
    if len(tree) == 1:
        return tree[0]
    elif query_range == 1:
        new_start_index = query_range[0] // length
        return query(tree, length, (new_start_index, query_range[0] % length), not axis)
    else:
        new_end_index = query_range[1] // length
        return query(tree, length, (query_range[0] % length, new_end_index), not axis)

