import itertools

def max_expression_value(expr):
    operands = set(expr.split('|'))
    operations = ['^', '&', '|']
    max_val = 0

    for operators in itertools.product(operations, repeat=len(expr)):
        res = expr.replace('&', operands[0]).replace('^', operands[1]).replace('|', operands[2])
        for operator in operators:
            res = expr.replace(operator, only_once(res, operator).split())

        max_val = max(max_val, int(eval(res)))

    return max_val

def only_once(expr, op):
    stack = []
    for c in expr:
        if c in ['0', '1']:
            stack.append(c)
        else:
            operands = set(stack.pop(0))
            stack.append(stack.pop(0) + operands.pop(0))
            stack.pop(0) # Discard 'ing' operator
    return ends(stack.pop(0))

def ends(expr):
    if '+' == expr[-1]:
        return expr[:-1]
    else:
        return expr

