def count_photos(r, c, viola_positions, k):
    viola_set = set(viola_positions)
    possible_photos = []

    # Iterate over all rectangles formed by selecting k viola positions
    for combo in combinations(viola_set, k):
        for rect in get_rectangles_between_combinations(r, c, combo):
            possible_photos.append(rect)

    return len(possible_photos)

def get_rectangles_between_combinations(r, c, viola_positions):
    rectangles = []
    distances = sorted(viola_positions)
    for start in range(len(distances) - 1):
        width = distances[start + 1] - distances[start] + 1
        up = 0
        for i in range(1, r + 1):
            if rect_any_in_rectangles([(i, None), (i, distances[start]) + (width, c) + (None, True)], r, c):
                for j in range(1, c + 1):
                    if rect_any_in_rectangles([(i, distances[start + 1]), (i, j)], r, c):
                        rectangles.append((i, up, (start + 1), j))
