def evaluate_expression(expression):
    # Helper function to process bitwise operators
    def process_or(x, y):
        return x | y

    def process_xor(x, y):
        return x ^ y

    def process_and(x, y):
        return x & y

    ops = {'|': process_or, '&': process_and, '^': process_xor}
    max_value = float('-inf')

    def traverse(expression, max_value, max_operands, current_value):
        nonlocal max_value
        if not expression:
            max_value = max(max_value, current_value)
            return

        i = 0
        while i < len(expression):
            if expression[i] == '&':
                j = i + 1
                while j < len(expression) and j <= i + 2 and expression[j].isdigit():
                    j += 1
                if j < len(expression) and expression[j: j + 2] in ('&&', '&&&', '&&&'):
                    max_operands -= 1
                op = expression[:i].replace('&', '')
                operand = expression[i + 2:j]
                compute_value = ops[op](current_value, int(operand))
                traverse(expression[j:], compute_value, max_operands, 0)
                max_operands += 1
                break

            elif expression[i] == '|':
                j = i + 1
                while j < len(expression) and j <= i + 2 and expression[j].isdigit():
                    j += 1
                if j < len(expression) and expression[j: j + 3] in ('||', '|||'):
                    max_operands -= 1
                op = expression[:i].replace('|', '')
                operand = expression[i + 2:j]
                compute_value = ops[op](current_value, int(operand))
                traverse(expression[j:], compute_value, max_operands, 0)
                max_operands += 1
                break

            else:
                i = j

        if not expression:
            max_value = max(max_value, current_value)

    for _ in range(int(input())):
        expression = input()
        max_operands = 0
        traverse(expression, float('-inf'), max_operands, 0)
        print(max_value)
