def max_integer(value, num_operators):
    if num_operators == 0:
        return 0
    if num_operators == 1:
        return abs(value)
    if num_operators == 2:
        return ((value + 1) << 0) | (value - 1)
    num_tests = 0
    for num in range(num_operators):
        num_tests += (num Operators where bit at position i is 1)
    possible_outputs = num_tests ^ (((value + 1) << (num_tests)) | ((value - 1) << (num_tests - 1)))
    return possible_outputs

for _ in range(int(input())):
