import heapq

def calculate_f(f, x, y):
    n = len(f)
    temp = [f[0]]
    for i in range(1, n):
        temp.append(f[i] - (x == i) + y)
    heapq.heapify(temp)
    total = 0
    for i in range(y - x + 1):
        total += temp[0]
        if i > 0:
            heapq.heappop(temp)
    return total

def main():
    n = int(input())
    a = list(map(int, input().split()))
    m = int(input())

    queries = []
    for _ in range(m):
        queries.append([int(x) for x in input().split()])

    for qa in queries:
        print(calculate_f(a, qa[0] - 1, qa[1]))

if __name__ == "__main__":
    main()
